$ErrorActionPreference = 'Stop'
Write-Host 'BuildMitra Engineering Specimen Alignment + Dynamic Geometry Fix' -ForegroundColor Cyan
$ProjectRoot = Split-Path -Parent $PSScriptRoot
if (-not (Test-Path (Join-Path $ProjectRoot 'package.json'))) { throw "BuildMitra project root not found: $ProjectRoot" }
Write-Host "Project: $ProjectRoot"
$Stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$BackupRoot = Join-Path $ProjectRoot "backups\isometric_alignment_$Stamp"
New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null
$ComponentDir = Join-Path $ProjectRoot 'components\engineering'
$ComponentPath = Join-Path $ComponentDir 'EngineeringSpecimen.tsx'
New-Item -ItemType Directory -Path $ComponentDir -Force | Out-Null
if (Test-Path $ComponentPath) {
  New-Item -ItemType Directory -Path (Join-Path $BackupRoot 'components\engineering') -Force | Out-Null
  Copy-Item $ComponentPath (Join-Path $BackupRoot 'components\engineering\EngineeringSpecimen.tsx') -Force
}
$ComponentBase64 = ''
[IO.File]::WriteAllBytes($ComponentPath, [Convert]::FromBase64String($ComponentBase64))
Write-Host 'Updated shared EngineeringSpecimen.tsx with true dimension scaling and rebar schedules.' -ForegroundColor Green
$Patches = @(
  [pscustomobject]@{ Path = 'pages/beam-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="beam" title="Dynamic Beam Specimen" material={inputs.grade} data={{ lengthFt: inputs.lengthFt, widthIn: inputs.widthIn, depthIn: inputs.depthIn, grade: inputs.grade, topDia: inputs.topDia, topNos: inputs.topNos, bottomDia: inputs.bottomDia, bottomNos: inputs.bottomNos, stirrupDia: inputs.stirrupDia, spacingMm: inputs.spacingMm, coverMm: inputs.coverMm, showSteel: calcResults.hasSteel, scopeOption }} />
'@ },
  [pscustomobject]@{ Path = 'pages/brick-work-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="masonry" title="Dynamic Brick / Block Specimen" material={calcMode === 'quick' ? quickInputs.blockType : detailedInputs.blockType} data={calcMode === 'quick' ? { length: quickInputs.plotLength, heightFt: 10, wallThicknessInches: quickInputs.internalWallSize.includes('4.5') ? 4.5 : quickInputs.internalWallSize.includes('6') ? 6 : 8, mortarThicknessMm: quickInputs.mortarThicknessMm } : { length: detailedInputs.length, heightFt: detailedInputs.height, wallThicknessInches: detailedInputs.wallThicknessInches, mortarThicknessMm: detailedInputs.mortarThicknessMm }} />
'@ },
  [pscustomobject]@{ Path = 'pages/footing-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="footing" title="Dynamic Footing Specimen" material={inputs.grade} data={{ lengthFt: inputs.lengthFt, widthFt: inputs.widthFt, depthFt: inputs.depthFt, widthIn: inputs.columnWidthIn, grade: inputs.grade, mainDia: inputs.mainDia, distDia: inputs.distDia, mainSpacingMm: inputs.mainSpacingMm, distSpacingMm: inputs.distSpacingMm, coverMm: inputs.coverMm, showSteel: calcResults.hasSteel, scopeOption }} />
'@ },
  [pscustomobject]@{ Path = 'pages/lintel-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="lintel" title="Dynamic Lintel Specimen" material={inputs.grade} data={{ lengthFt: inputs.clearLenFt, clearLenFt: inputs.clearLenFt, widthIn: inputs.widthIn, depthIn: inputs.depthIn, grade: inputs.grade, bearingMm: inputs.bearingMm, mainDia: inputs.mainDia, mainNos: inputs.mainNos, topDia: inputs.topDia, topNos: inputs.topNos, stirrupDia: inputs.stirrupDia, spacingMm: inputs.spacingMm, coverMm: inputs.coverMm, showSteel: calcResults.hasSteel, scopeOption }} />
'@ },
  [pscustomobject]@{ Path = 'pages/pile-foundation-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="pile" title="Dynamic Pile Specimen" material={inputs.grade} data={{ heightFt: inputs.lengthFt, lengthFt: inputs.lengthFt, diameterMm: inputs.diameterFt * 304.8, grade: inputs.grade, mainDia: inputs.mainDia, mainNos: inputs.mainNos, stirrupDia: inputs.tieDia, tieSpacingMm: inputs.tieSpacingMm, coverMm: inputs.coverMm, showSteel: calcResults.hasSteel, scopeOption }} />
'@ },
  [pscustomobject]@{ Path = 'pages/rcc-slab-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="slab" title="Dynamic RCC Slab Specimen" material={calcMode === 'quick' ? quickInputs.concreteGrade : detailedInputs.grade} data={calcMode === 'quick' ? { lengthFt: quickInputs.plotLength, widthFt: quickInputs.plotWidth, depthIn: quickInputs.slabThicknessMm / 25.4, grade: quickInputs.concreteGrade, mainDia: quickInputs.mainDia, distDia: quickInputs.distDia, mainSpacingMm: quickInputs.mainSpacingMm, distSpacingMm: quickInputs.distSpacingMm, coverMm: quickInputs.coverMm, showSteel: true } : { lengthFt: detailedInputs.length, widthFt: detailedInputs.width, depthIn: detailedInputs.thicknessMm / 25.4, grade: detailedInputs.grade, mainDia: detailedInputs.mainDia, distDia: detailedInputs.distDia, mainSpacingMm: detailedInputs.mainSpacingMm, distSpacingMm: detailedInputs.distSpacingMm, coverMm: detailedInputs.coverMm, showSteel: true }} />
'@ },
  [pscustomobject]@{ Path = 'pages/rcc-steel-building-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="steel-building" title="Dynamic RCC Building Specimen" material={calcMode} data={{ lengthFt: inputs.plotLength, widthFt: inputs.plotWidth, heightFt: inputs.floorHeight, type: calcMode }} />
'@ },
  [pscustomobject]@{ Path = 'pages/retaining-wall-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="retaining-wall" title="Dynamic Retaining Wall Specimen" material={inputs.grade} data={{ lengthFt: inputs.lengthFt, heightFt: inputs.heightFt, widthIn: inputs.thicknessFt * 12, grade: inputs.grade, vertDia: inputs.vertDia, horizDia: inputs.horizDia, vertSpacingMm: inputs.vertSpacingMm, horizSpacingMm: inputs.horizSpacingMm, coverMm: inputs.coverMm, showSteel: calcResults.hasSteel, scopeOption }} />
'@ },
  [pscustomobject]@{ Path = 'pages/roof-truss-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="roof-truss" title="Dynamic Roof Truss Specimen" material={inputs.roofType} data={{ lengthFt: inputs.lengthFt, spanFt: inputs.widthFt, heightFt: inputs.riseFt, riseFt: inputs.riseFt, trussType: inputs.structureType, type: inputs.roofType }} />
'@ },
  [pscustomobject]@{ Path = 'pages/septic-tank-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="septic-tank" title="Dynamic Septic Tank Specimen" material={inputs.wallMaterial} data={{ lengthFt: inputs.lengthFt, widthFt: inputs.widthFt, heightFt: inputs.depthFt, wallType: inputs.wallMaterial, grade: inputs.grade, mainDia: inputs.mainDia, distDia: inputs.distDia, mainSpacingMm: inputs.mainSpacingMm, distSpacingMm: inputs.distSpacingMm, coverMm: inputs.coverMm, showSteel: true }} />
'@ },
  [pscustomobject]@{ Path = 'pages/staircase-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="staircase" title="Dynamic Staircase Specimen" material={inputs.finishType} data={{ heightFt: inputs.floorHeight, widthFt: inputs.widthFt, treadIn: inputs.treadIn, riserIn: inputs.riserIn, finishType: inputs.finishType, railingType: inputs.railingType, mainDia: inputs.mainDia, distDia: inputs.distDia, mainSpacingMm: inputs.mainSpacingMm, coverMm: inputs.coverMm, showSteel: calcResults.hasSteel, scopeOption }} />
'@ },
  [pscustomobject]@{ Path = 'pages/water-tank-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="water-tank" title="Dynamic Water Tank Specimen" material={inputs.wallType} data={{ lengthFt: inputs.lengthFt, widthFt: inputs.widthFt, heightFt: inputs.heightFt, wallType: inputs.wallType, grade: inputs.grade, wallThickIn: inputs.wallThickIn, mainDia: inputs.mainDia, distDia: inputs.distDia, mainSpacingMm: inputs.mainSpacingMm, distSpacingMm: inputs.distSpacingMm, coverMm: inputs.coverMm, showSteel: calcResults.hasSteel, scopeOption }} />
'@ },
  [pscustomobject]@{ Path = 'pages/paint-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="paint" title="Dynamic Paint Surface Specimen" material={calcMode === 'quick' ? quickInputs.paintType : detailedInputs.paintType} data={calcMode === 'quick' ? { lengthFt: Math.sqrt(quickInputs.totalArea), heightFt: Math.sqrt(quickInputs.totalArea), type: quickInputs.paintType } : { lengthFt: detailedInputs.length, heightFt: detailedInputs.height, type: detailedInputs.paintType }} />
'@ },
  [pscustomobject]@{ Path = 'pages/plaster-calculator.tsx'; Snippet = @'
      <EngineeringSpecimen kind="plaster" title="Dynamic Plaster Specimen" material={calcMode === 'quick' ? quickInputs.plasterType : detailedInputs.plasterType} data={calcMode === 'quick' ? { lengthFt: quickInputs.plotLength, heightFt: 10, type: quickInputs.plasterType } : { lengthFt: detailedInputs.length, heightFt: detailedInputs.height, type: detailedInputs.plasterType }} />
'@ }
)
$LayoutCss = @'
      <style jsx>{`
        .engineering-top-layout {
          display: grid;
          grid-template-columns: minmax(0, 1fr) 260px;
          gap: 16px;
          align-items: start;
          margin-bottom: 18px;
        }
        .engineering-top-left { min-width: 0; overflow: hidden; }
        .engineering-specimen-top {
          width: 260px;
          position: sticky;
          top: 12px;
          align-self: start;
          z-index: 2;
        }
        @media (max-width: 900px) {
          .engineering-top-layout { grid-template-columns: 1fr; }
          .engineering-specimen-top {
            width: 100%; max-width: 260px; position: static;
            margin-left: auto; margin-right: auto;
          }
        }
      `}</style>
'@
foreach ($Patch in $Patches) {
  $FilePath = Join-Path $ProjectRoot $Patch.Path
  if (-not (Test-Path $FilePath)) { Write-Warning "Skipped missing file: $($Patch.Path)"; continue }
  $Saved = Join-Path $BackupRoot $Patch.Path
  New-Item -ItemType Directory -Path (Split-Path $Saved -Parent) -Force | Out-Null
  Copy-Item $FilePath $Saved -Force
  $Content = Get-Content -LiteralPath $FilePath -Raw
  if ($Content -notmatch "import EngineeringSpecimen from '../components/engineering/EngineeringSpecimen';") {
    $Anchor = "import MarketRateTrend from '../components/ui/MarketRateTrend';"
    if (-not $Content.Contains($Anchor)) { throw "Import anchor missing in $($Patch.Path)" }
    $Content = $Content.Replace($Anchor, $Anchor + "`r`nimport EngineeringSpecimen from '../components/engineering/EngineeringSpecimen';")
  }
  $Content = [regex]::Replace($Content, '(?m)^\s*<EngineeringSpecimen\b[^\r\n]*/>\s*$', '')
  $PatternWithDropdown = '(?s)(<div style=\{styles\.container\}>\s*)(.*?<MarketRateTrend\s*/>\s*.*?<div style=\{styles\.dropdownCard\}>.*?</div>)(\s*(?:\{/\*|<div style=\{styles\.stepperCard\}>))'
  $Match = [regex]::Match($Content, $PatternWithDropdown)
  if (-not $Match.Success) {
    $PatternNoDropdown = '(?s)(<div style=\{styles\.container\}>\s*)(.*?<MarketRateTrend\s*/>)(\s*(?:\{/\*|<div style=\{styles\.stepperCard\}>))'
    $Match = [regex]::Match($Content, $PatternNoDropdown)
  }
  if (-not $Match.Success) { throw "Top placement anchor not found in $($Patch.Path)" }
  $Replacement = $Match.Groups[1].Value + "      <div className=`"engineering-top-layout`">`r`n        <div className=`"engineering-top-left`">`r`n" + $Match.Groups[2].Value + "`r`n        </div>`r`n        <div className=`"engineering-specimen-top`">`r`n" + $Patch.Snippet.TrimEnd() + "`r`n        </div>`r`n      </div>`r`n" + $LayoutCss + $Match.Groups[3].Value
  $Content = $Content.Substring(0,$Match.Index) + $Replacement + $Content.Substring($Match.Index+$Match.Length)
  [IO.File]::WriteAllText($FilePath, $Content, [Text.UTF8Encoding]::new($false))
  Write-Host "Corrected placement + dynamic specimen: $($Patch.Path)" -ForegroundColor Green
}
Write-Host "Backup created: $BackupRoot" -ForegroundColor Cyan
Write-Host 'Running Next.js production build...' -ForegroundColor Cyan
Push-Location $ProjectRoot
try {
  npm run build
  if ($LASTEXITCODE -ne 0) { throw "npm run build failed with exit code $LASTEXITCODE" }
} catch {
  Write-Host 'BUILD FAILED. Restoring all changed files...' -ForegroundColor Red
  foreach ($Patch in $Patches) {
    $Saved = Join-Path $BackupRoot $Patch.Path
    $Target = Join-Path $ProjectRoot $Patch.Path
    if (Test-Path $Saved) { Copy-Item $Saved $Target -Force }
  }
  $SavedComponent = Join-Path $BackupRoot 'components\engineering\EngineeringSpecimen.tsx'
  if (Test-Path $SavedComponent) { Copy-Item $SavedComponent $ComponentPath -Force }
  throw
} finally { Pop-Location }
Write-Host ''
Write-Host 'BUILD SUCCESS - all shared specimens now match Column top-right placement.' -ForegroundColor Green
Write-Host 'Dimension changes now move/scale SVG geometry; reinforcement calculators show bar numbers, diameters, spacing and cover.' -ForegroundColor Green
